213	/** Scales the wide-screen canvas to fit its box (a CSS variable, so it costs no re-render). */
214	function useCanvasScale(w: number, h: number) {
215	  const boxRef = useRef<HTMLDivElement>(null);
216	  useEffect(() => {
217	    const box = boxRef.current;
218	    if (!box) return;
219	    const wide = window.matchMedia("(min-width: 1280px)");
220	    const update = () => {
221	      if (!wide.matches) {
222	        box.style.removeProperty("--demo-scale");
223	        return;
224	      }
225	      const rect = box.getBoundingClientRect();
226	      const s = Math.min(rect.width / w, rect.height / h, MAX_SCALE);
227	      box.style.setProperty("--demo-scale", String(Math.max(0.5, s)));
228	    };
229	    update();
230	    const ro = new ResizeObserver(update);
231	    ro.observe(box);
232	    wide.addEventListener("change", update);
233	    return () => {
234	      ro.disconnect();
235	      wide.removeEventListener("change", update);
236	    };
237	  }, [w, h]);
238	  return boxRef;
239	}
